// NewExpression parses a literal or a single {{ expression }} template.
func NewExpression(input string) (*Expression, error) {
	prefix, body, suffix, template, err := splitTemplate(input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !template {
		return &Expression{expr: StringLitExpr{Value: body}}, nil
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must evaluate to a string, got %s", input, expr.Kind())
	}
	return &Expression{expr: expr, prefix: prefix, suffix: suffix}, nil
