// Matcher matches a string against a parsed matching expression.
type Matcher interface{ Match(string) bool }

// MatcherFn adapts a function to Matcher.
type MatcherFn func(string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }

// MatchExpression contains fixed text around a boolean expression.
type MatchExpression struct {
	prefix, suffix string
	expr           Expr
}

// Match first checks fixed text, then evaluates the boolean AST on the middle.
func (m *MatchExpression) Match(in string) bool {
	if len(in) < len(m.prefix)+len(m.suffix) ||
		!strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) {
		return false
	}
	middle := in[len(m.prefix) : len(in)-len(m.suffix)]
	value, err := evaluateBool(m.expr, EvaluateContext{MatcherInput: middle})
	return err == nil && value
}

// NewMatcher accepts literal/glob strings, anchored raw regexes, and boolean
// templates built from regexp.match and regexp.not_match.
func NewMatcher(input string) (Matcher, error) {
	prefix, body, suffix, template, err := splitTemplate(input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !template {
		re, err := compileRegexp(body, true)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &MatchExpression{expr: RegexpMatchExpr{Pattern: re.String(), re: re}}, nil
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher expression %q must evaluate to a boolean, got %s", input, expr.Kind())
	}
	return &MatchExpression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

// NewAnyMatcher returns a matcher that accepts any of the supplied patterns.
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, value := range in {
		matcher, err := NewMatcher(value)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = matcher
	}
	return MatcherFn(func(value string) bool {
		for _, matcher := range matchers {
			if matcher.Match(value) {
				return true
			}
		}
		return false
	}), nil
}

// splitTemplate trims only the outside of the input and the content between
// {{ and }}. Quoted strings inside a template are left untouched.
func splitTemplate(input string) (prefix, body, suffix string, template bool, err error) {
	trimmed := strings.TrimSpace(input)
	open := strings.Index(trimmed, "{{")
	if open < 0 {
		if strings.Contains(trimmed, "}}") {
			return "", "", "", false, malformedTemplate(input)
		}
		return "", trimmed, "", false, nil
	}
	prefix = trimmed[:open]
	bodyStart := open + 2
	quote := byte(0)
	escaped := false
	for i := bodyStart; i < len(trimmed)-1; i++ {
		c := trimmed[i]
		if quote != 0 {
			if escaped {
				escaped = false
			} else if c == '"'\\\\' && quote "'!= '"'"'`'"' {
				escaped = true
			} else if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\\'', '\"', '"'`'"':
			quote = c
		case '{':
			if trimmed[i+1] == '{' {
				return \"\", \"\", \"\", false, malformedTemplate(input)
			}
		case '}':
			if trimmed[i+1] == '}' {
				body = strings.TrimSpace(trimmed[bodyStart:i])
				suffix = trimmed[i+2:]
				if body == \"\" || strings.Contains(suffix, \"{{\") || strings.Contains(suffix, \"}}\") || strings.Contains(prefix, \"}}\") {
					return \"\", \"\", \"\", false, malformedTemplate(input)
				}
				return prefix, body, suffix, true, nil
			}
		}
	}
	return \"\", \"\", \"\", false, malformedTemplate(input)
}

func malformedTemplate(input string) error {
	return trace.BadParameter(\"malformed template usage in %q: expected one {{ expression }}\", input)
