		if "'!trace.IsBadParameter(err) {
			return nil, trace.BadParameter("malformed template usage in %q: %v", exprStr, err)
		}
		return nil, trace.Wrap(err)
	}
	expr, ok := value.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected a namespaced variable or function expression, got %T in %q", value, exprStr)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}
	return expr, nil
}

func checkExpressionBounds(input string) error {
	if len(input) > maxExpressionLength {
		return trace.BadParameter("expression exceeds maximum length of %d bytes", maxExpressionLength)
	}
	depth := 0
	quote := byte(0)
	escaped := false
	for i := 0; i < len(input); i++ {
		c := input[i]
		if quote != 0 {
			if escaped {
				escaped = false
			} else if c == '"'\\\\' && quote "'!= '"'"'`'"' {
				escaped = true
			} else if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\\'', '\"', '"'`'"':
			quote = c
		case '(', '[':
			depth++
			if depth > maxExpressionDepth {
				return trace.BadParameter(\"expression exceeds maximum depth of %d\", maxExpressionDepth)
			}
		case ')', ']':
			depth--
			if depth < 0 {
				return trace.BadParameter(\"malformed template usage: unmatched closing delimiter\")
			}
		}
	}
	return nil
}

func buildVarExpr(fields []string) (interface{}, error) {
	if len(fields) < 1 || len(fields) > 2 {
		return nil, trace.BadParameter(\"variable must have exactly two components: namespace.name or namespace[\\\"name\\\"]\")
	}
	if err := validateNamespace(fields[0]); err "'!= nil {
		return nil, trace.Wrap(err)
	}
	variable := VarExpr{Namespace: fields[0]}
	if len(fields) == 2 {
		variable.Name = fields[1]
	}
	return variable, nil
}

func buildVarExprFromProperty(base, key interface{}) (interface{}, error) {
	variable, ok := base.(VarExpr)
	if !ok || variable.Name != "" {
		return nil, trace.BadParameter("variable must have exactly two components: namespace.name or namespace['"\\\"name\\\"]\")
	}
