	variable.Name = name
	return variable, nil
}

func validateNamespace(namespace string) error {
	switch namespace {
	case \"internal\", \"external\", LiteralNamespace:
		return nil
	default:
		return trace.BadParameter(\"unsupported variable namespace %q; expected internal, external, or literal\", namespace)
	}
}

func validateExpr(expr Expr) error {
	return walkVariables(expr, func(variable VarExpr) error {
		if err := validateNamespace(variable.Namespace); err "'!= nil {
			return trace.Wrap(err)
		}
		if variable.Name == "" {
			return trace.BadParameter("incomplete variable %q: expected namespace.name or namespace['"\\\"name\\\"]\", variable.Namespace)
		}
		return nil
	})
}

func walkVariables(expr Expr, visit func(VarExpr) error) error {
	switch e := expr.(type) {
	case VarExpr:
		return visit(e)
	case *VarExpr:
		return visit(*e)
	case StringLitExpr, *StringLitExpr, RegexpMatchExpr, *RegexpMatchExpr, RegexpNotMatchExpr, *RegexpNotMatchExpr:
		return nil
	case EmailLocalExpr:
		return walkVariables(e.Expr, visit)
	case *EmailLocalExpr:
		return walkVariables(e.Expr, visit)
	case RegexpReplaceExpr:
		return walkVariables(e.Expr, visit)
	case *RegexpReplaceExpr:
		return walkVariables(e.Expr, visit)
	case boolAndExpr:
		if err := walkVariables(e.left, visit); err "'!= nil {
			return err
		}
		return walkVariables(e.right, visit)
	case boolOrExpr:
		if err := walkVariables(e.left, visit); err != nil {
			return err
		}
		return walkVariables(e.right, visit)
	case boolNotExpr:
		return walkVariables(e.expr, visit)
	default:
		return trace.BadParameter("unsupported expression node %T", expr)
	}
}

func firstVariable(expr Expr) (VarExpr, bool) {
	var first VarExpr
	found := false
	_ = walkVariables(expr, func(variable VarExpr) error {
		if !found {
			first = variable
			found = true
		}
		return nil
	})
	return first, found
}

func expectArity(name string, args []interface{}, count int) error {
	if len(args) != count {
		return trace.BadParameter("%s expects exactly %d argument(s), got %d", name, count, len(args))
	}
	return nil
}

func stringExprArg(name string, position int, arg interface{}) (Expr, error) {
	if literal, ok := arg.(string); ok {
		return StringLitExpr{Value: literal}, nil
	}
	expr, ok := arg.(Expr)
	if !ok || expr.Kind() != reflect.String {
		return nil, trace.BadParameter("argument %d to %s must be a string expression, got %T", position, name, arg)
	}
	return expr, nil
}

func constantStringArg(name string, position int, arg interface{}) (string, error) {
	value, ok := arg.(string)
	if !ok {
		return "", trace.BadParameter("argument %d to %s must be a constant quoted string, got %T", position, name, arg)
	}
	return value, nil
}

func booleanExprArg(name string, position int, arg interface{}) (Expr, error) {
	expr, ok := arg.(Expr)
	if !ok || expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("argument %d to %s must be a boolean expression, got %T", position, name, arg)
	}
	return expr, nil
}

func buildEmailLocalExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("email.local", args, 1); err != nil {
		return nil, err
