	arg, err := stringExprArg("email.local", 1, args[0])
	if err != nil {
		return nil, err
	}
	return EmailLocalExpr{Expr: arg}, nil
}

func buildRegexpReplaceExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("regexp.replace", args, 3); err != nil {
		return nil, err
