func buildRegexpMatchExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("regexp.match", args, 1); err != nil {
		return nil, err
	}
	pattern, err := constantStringArg("regexp.match", 1, args[0])
	if err != nil {
		return nil, err
	}
	re, err := compileRegexp(pattern, false)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return RegexpMatchExpr{Pattern: pattern, re: re}, nil
}

func buildRegexpNotMatchExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("regexp.not_match", args, 1); err != nil {
		return nil, err
	}
	pattern, err := constantStringArg("regexp.not_match", 1, args[0])
	if err != nil {
		return nil, err
	}
	re, err := compileRegexp(pattern, false)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return RegexpNotMatchExpr{Pattern: pattern, re: re}, nil
