func buildBoolAndExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("&&", args, 2); err != nil {
		return nil, err
	}
	left, err := booleanExprArg("&&", 1, args[0])
	if err != nil {
		return nil, err
	}
	right, err := booleanExprArg("&&", 2, args[1])
	if err != nil {
		return nil, err
	}
	return boolAndExpr{left: left, right: right}, nil
