func TestExpressionInterpolate(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name   string
		input  string
		traits map[string][]string
		want   []string
	}{
		{"bare literal", "  production  ", nil, []string{"production"}},
		{"literal namespace", "{{literal.production}}", nil, []string{"production"}},
		{"dot variable and whitespace", "  {{  internal.logins  }}  ", map[string][]string{"logins": {"alice", "bob"}}, []string{"alice", "bob"}},
		{"bracket variable", `{{external["email address"]}}`, map[string][]string{"email address": {"alice@example.com"}}, []string{"alice@example.com"}},
		{"prefix and suffix", "  IAM#{{internal.logins}};  ", map[string][]string{"logins": {"alice", "bob"}}, []string{"IAM#alice;", "IAM#bob;"}},
		{"email local", `{{email.local(external.email)}}`, map[string][]string{"email": {"Alice <alice@example.com>", "bob@example.com"}}, []string{"alice", "bob"}},
		{"nested calls", `user-{{regexp.replace(email.local(external.email), "^([^.]+)\\..*$", "$1")}}`, map[string][]string{"email": {"alice.smith@example.com", "bob.jones@example.com"}}, []string{"user-alice", "user-bob"}},
		{"constant replace source", `{{regexp.replace("foo-bar", "^foo-(.*)$", "$1")}}`, nil, []string{"bar"}},
		{"constant email source", `{{email.local("Alice <alice@example.com>")}}`, nil, []string{"alice"}},
		{"quoted whitespace retained", `{{regexp.replace(" a ", "^ a $", "hit")}}`, nil, []string{"hit"}},
		{"unmatched values omitted", `{{regexp.replace(internal.logins, "^foo-(.*)$", "$1")}}`, map[string][]string{"logins": {"bad", "foo-alice", "foo-bob"}}, []string{"alice", "bob"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			expr, err := NewExpression(tt.input)
			require.NoError(t, err)
			values, err := expr.Interpolate(tt.traits)
			require.NoError(t, err)
			require.Equal(t, tt.want, values)
		})
	}
}

