// NewMatcher accepts literal/glob strings, anchored raw regexes, and boolean
// templates built from regexp.match and regexp.not_match.
func NewMatcher(input string) (Matcher, error) {
	prefix, body, suffix, template, err := splitTemplate(input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !template {
		if len(body) > maxExpressionLength {
			return nil, trace.BadParameter("matcher expression exceeds maximum length of %d bytes", maxExpressionLength)
		}
		re, err := compileRegexp(body, true)
