}

// NewAnyMatcher returns a matcher that accepts any of the supplied patterns.
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, value := range in {
		matcher, err := NewMatcher(value)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = matcher
	}
	return MatcherFn(func(value string) bool {
		for _, matcher := range matchers {
			if matcher.Match(value) {
				return true
			}
		}
		return false
	}), nil
}

// splitTemplate trims only the outside of the input and the content between
// {{ and }}. Quoted strings inside a template are left untouched.
func splitTemplate(input string) (prefix, body, suffix string, template bool, err error) {
	trimmed := strings.TrimSpace(input)
	open := strings.Index(trimmed, "{{")
	if open < 0 {
		if strings.Contains(trimmed, "}}") {
			return "", "", "", false, malformedTemplate(input)
		}
		return "", trimmed, "", false, nil
	}
	prefix = trimmed[:open]
	bodyStart := open + 2
	quote := byte(0)
	escaped := false
	for i := bodyStart; i < len(trimmed)-1; i++ {
		c := trimmed[i]
		if quote != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' && quote != '`' {
				escaped = true
			} else if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"', '`':
			quote = c
		case '{':
			if trimmed[i+1] == '{' {
				return "", "", "", false, malformedTemplate(input)
			}
		case '}':
			if trimmed[i+1] == '}' {
				body = strings.TrimSpace(trimmed[bodyStart:i])
				suffix = trimmed[i+2:]
				if body == "" || strings.ContainsAny(prefix, "{}") || strings.ContainsAny(suffix, "{}") {
					return "", "", "", false, malformedTemplate(input)
				}
				return prefix, body, suffix, true, nil
			}
		}
	}
	return "", "", "", false, malformedTemplate(input)
}

func malformedTemplate(input string) error {
	return trace.BadParameter("malformed template usage in %q: expected one {{ expression }}", input)
}

// parse builds typed nodes with the predicate parser. Its callbacks construct
// nodes rather than evaluating trait values during parsing.
func parse(exprStr string) (Expr, error) {
	if err := checkExpressionBounds(exprStr); err != nil {
		return nil, trace.Wrap(err)
	}
	parser, err := predicate.NewParser(predicate.Def{
		Functions: map[string]interface{}{
			"email.local":      buildEmailLocalExpr,
			"regexp.replace":   buildRegexpReplaceExpr,
			"regexp.match":     buildRegexpMatchExpr,
			"regexp.not_match": buildRegexpNotMatchExpr,
		},
		Operators: predicate.Operators{
			AND: buildBoolAndExpr,
			OR:  buildBoolOrExpr,
			NOT: buildBoolNotExpr,
		},
		GetIdentifier: buildVarExpr,
		GetProperty:   buildVarExprFromProperty,
	})
	if err != nil {
		return nil, trace.BadParameter("failed to initialize expression parser: %v", err)
	}
	value, err := parser.Parse(exprStr)
	if err != nil {
		if strings.Contains(err.Error(), "unsupported selector type") {
			return nil, trace.BadParameter("variable must have exactly two components: namespace.name or namespace[\"name\"]: %v", err)
		}
		if !trace.IsBadParameter(err) {
			return nil, trace.BadParameter("malformed template usage in %q: %v", exprStr, err)
		}
		return nil, trace.Wrap(err)
	}
	expr, ok := value.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected a namespaced variable or function expression, got %T in %q", value, exprStr)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}
	return expr, nil
}

func checkExpressionBounds(input string) error {
	if len(input) > maxExpressionLength {
		return trace.BadParameter("expression exceeds maximum length of %d bytes", maxExpressionLength)
	}
	depth := 0
	quote := byte(0)
	escaped := false
	for i := 0; i < len(input); i++ {
		c := input[i]
		if quote != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' && quote != '`' {
				escaped = true
			} else if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"', '`':
			quote = c
		case '(', '[':
			depth++
			if depth > maxExpressionDepth {
				return trace.BadParameter("expression exceeds maximum depth of %d", maxExpressionDepth)
			}
		case ')', ']':
			depth--
			if depth < 0 {
				return trace.BadParameter("malformed template usage: unmatched closing delimiter")
			}
		}
	}
	return nil
}

func buildVarExpr(fields []string) (interface{}, error) {
	if len(fields) < 1 || len(fields) > 2 {
		return nil, trace.BadParameter("variable must have exactly two components: namespace.name or namespace[\"name\"]")
	}
	if err := validateNamespace(fields[0]); err != nil {
		return nil, trace.Wrap(err)
	}
	variable := VarExpr{Namespace: fields[0]}
	if len(fields) == 2 {
		variable.Name = fields[1]
	}
	return variable, nil
}

func buildVarExprFromProperty(base, key interface{}) (interface{}, error) {
	variable, ok := base.(VarExpr)
	if !ok || variable.Name != "" {
		return nil, trace.BadParameter("variable must have exactly two components: namespace.name or namespace[\"name\"]")
	}
	name, ok := key.(string)
	if !ok || name == "" {
		return nil, trace.BadParameter("variable index must be a non-empty quoted name in namespace[\"name\"]")
	}
	variable.Name = name
	return variable, nil
}

func validateNamespace(namespace string) error {
	switch namespace {
	case "internal", "external", LiteralNamespace:
		return nil
	default:
		return trace.BadParameter("unsupported variable namespace %q; expected internal, external, or literal", namespace)
	}
}

func validateExpr(expr Expr) error {
	return walkVariables(expr, func(variable VarExpr) error {
		if err := validateNamespace(variable.Namespace); err != nil {
			return trace.Wrap(err)
		}
		if variable.Name == "" {
			return trace.BadParameter("incomplete variable %q: expected namespace.name or namespace[\"name\"]", variable.Namespace)
		}
		return nil
	})
}

func walkVariables(expr Expr, visit func(VarExpr) error) error {
	switch e := expr.(type) {
	case VarExpr:
		return visit(e)
	case *VarExpr:
		return visit(*e)
	case StringLitExpr, *StringLitExpr, RegexpMatchExpr, *RegexpMatchExpr, RegexpNotMatchExpr, *RegexpNotMatchExpr:
		return nil
	case EmailLocalExpr:
		return walkVariables(e.Expr, visit)
	case *EmailLocalExpr:
		return walkVariables(e.Expr, visit)
	case RegexpReplaceExpr:
		return walkVariables(e.Expr, visit)
	case *RegexpReplaceExpr:
		return walkVariables(e.Expr, visit)
	case boolAndExpr:
		if err := walkVariables(e.left, visit); err != nil {
			return err
		}
		return walkVariables(e.right, visit)
	case boolOrExpr:
		if err := walkVariables(e.left, visit); err != nil {
			return err
		}
		return walkVariables(e.right, visit)
	case boolNotExpr:
		return walkVariables(e.expr, visit)
	default:
		return trace.BadParameter("unsupported expression node %T", expr)
	}
}

func firstVariable(expr Expr) (VarExpr, bool) {
	var first VarExpr
	found := false
	_ = walkVariables(expr, func(variable VarExpr) error {
		if !found {
			first = variable
			found = true
		}
		return nil
	})
	return first, found
}

func expectArity(name string, args []interface{}, count int) error {
	if len(args) != count {
		return trace.BadParameter("%s expects exactly %d argument(s), got %d", name, count, len(args))
	}
	return nil
}

func stringExprArg(name string, position int, arg interface{}) (Expr, error) {
	if literal, ok := arg.(string); ok {
		return StringLitExpr{Value: literal}, nil
	}
	expr, ok := arg.(Expr)
	if !ok || expr.Kind() != reflect.String {
		return nil, trace.BadParameter("argument %d to %s must be a string expression, got %T", position, name, arg)
	}
	return expr, nil
}

func constantStringArg(name string, position int, arg interface{}) (string, error) {
	value, ok := arg.(string)
	if !ok {
		return "", trace.BadParameter("argument %d to %s must be a constant quoted string, got %T", position, name, arg)
	}
	return value, nil
}

func booleanExprArg(name string, position int, arg interface{}) (Expr, error) {
	expr, ok := arg.(Expr)
	if !ok || expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("argument %d to %s must be a boolean expression, got %T", position, name, arg)
	}
	return expr, nil
}

func buildEmailLocalExpr(args ...interface{}) (Expr, error) {
	if err := expectArity("email.local", args, 1); err != nil {
		return nil, err
	}
	arg, err := stringExprArg("email.local", 1, args[0])
	if err != nil {
		return nil, err
	}
	return EmailLocalExpr{Expr: arg}, nil
}

