func TestASTNodeContract(t *testing.T) {
	t.Parallel()
	ctx := EvaluateContext{
		VarValue: func(variable VarExpr) ([]string, error) {
			require.Equal(t, VarExpr{Namespace: "external", Name: "email"}, variable)
			return []string{"alice@example.com"}, nil
		},
		MatcherInput: "foo",
	}
	tests := []struct {
		name   string
		expr   Expr
		kind   reflect.Kind
		format string
		value  any
	}{
		{"string literal", StringLitExpr{Value: "a b"}, reflect.String, `"a b"`, []string{"a b"}},
		{"variable", VarExpr{Namespace: "external", Name: "email"}, reflect.String, "external.email", []string{"alice@example.com"}},
		{"email local", EmailLocalExpr{Expr: StringLitExpr{Value: "Alice <alice@example.com>"}}, reflect.String, `email.local("Alice <alice@example.com>")`, []string{"alice"}},
		{"regexp replace", RegexpReplaceExpr{Expr: StringLitExpr{Value: "x-42"}, Pattern: `^x-(.*)$`, Replacement: "$1"}, reflect.String, `regexp.replace("x-42", "^x-(.*)$", "$1")`, []string{"42"}},
		{"regexp match", RegexpMatchExpr{Pattern: "^foo$"}, reflect.Bool, `regexp.match("^foo$")`, true},
		{"regexp not match", RegexpNotMatchExpr{Pattern: "^bar$"}, reflect.Bool, `regexp.not_match("^bar$")`, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			require.Equal(t, tt.kind, tt.expr.Kind())
			require.Equal(t, tt.format, tt.expr.String())
			value, err := tt.expr.Evaluate(ctx)
			require.NoError(t, err)
			require.Equal(t, tt.value, value)
		})
	}
}
